import { connection } from 'next/server'
import { unstable_rethrow } from 'next/navigation'

type UserPreferences = Record<string, unknown>

// User-specific data that changes on every request, so it must never be
// prerendered at build time or served from the cache.
async function getUserPreferences(): Promise<UserPreferences | null> {
  // Opt this component out of prerendering: everything below runs at request time.
  await connection()

  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    if (!res.ok) throw new Error(`Failed to fetch preferences: ${res.status}`)
    return res.json()
  } catch (err) {
    // Let Next.js internal errors (e.g. dynamic rendering bailouts) propagate.
    unstable_rethrow(err)
    console.error(err)
    return null
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      {preferences ? (
        <dl>
          {Object.entries(preferences).map(([key, value]) => (
            <div key={key}>
              <dt>{key}</dt>
              <dd>
                {typeof value === 'object' && value !== null
                  ? JSON.stringify(value)
                  : String(value)}
              </dd>
            </div>
          ))}
        </dl>
      ) : (
        <p>Unable to load your preferences right now.</p>
      )}
    </div>
  )
}

